# SorobanTransactionData.ext is a union { 0: void; 1: SorobanResourcesExtV0 }
# since protocol 23 (CAP-66, archived entries to restore). stellar_base keeps
# ExtensionPoint (only arm 0), and the failure surfaces as a FunctionClauseError
# raised inside XDR.UnionError.exception/1, not as an XDR error.
Code.eval_file("common.exs", __DIR__)
alias StellarBase.XDR

# SorobanTransactionData of pubnet tx 65486053:349 (ext v1, archived_soroban_entries [1]),
# re-encoded by rs-stellar-xdr 30.0.0.
sd = Base.decode64!("")
R.try_decode("A. real SorobanTransactionData with ext v1", fn -> XDR.SorobanTransactionData.decode_xdr(sd) end)
